CREATE TABLE IF NOT EXISTS match_report_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,match_report_id BIGINT UNSIGNED NOT NULL,version_number INT UNSIGNED NOT NULL,snapshot_json JSON NOT NULL,reason TEXT NULL,status VARCHAR(30) NOT NULL,created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,UNIQUE KEY report_version(match_report_id,version_number),FOREIGN KEY(match_report_id) REFERENCES match_reports(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS match_officials (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,match_id BIGINT UNSIGNED NOT NULL,person_id BIGINT UNSIGNED NULL,role VARCHAR(60) NOT NULL,name VARCHAR(180) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(match_id) REFERENCES matches(id),FOREIGN KEY(person_id) REFERENCES people(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE match_events ADD COLUMN version_number INT UNSIGNED NOT NULL DEFAULT 1 AFTER is_cancelled, ADD COLUMN correction_reason TEXT NULL AFTER version_number, ADD COLUMN created_by BIGINT UNSIGNED NULL AFTER correction_reason, ADD FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL;
